const n = (x) => num(String(x));
const MON = {
  mr: ['जानेवारी', 'फेब्रुवारी', 'मार्च', 'एप्रिल', 'मे', 'जून', 'जुलै', 'ऑगस्ट', 'सप्टेंबर', 'ऑक्टोबर', 'नोव्हेंबर', 'डिसेंबर'],
  en: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'],
};
const WK = { mr: ['रविवार', 'सोमवार', 'मंगळवार', 'बुधवार', 'गुरुवार', 'शुक्रवार', 'शनिवार'], en: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'] };
const SV_MR = { Yuva: 'युवा', Vikriti: 'विकृति', Tarana: 'तारण', Manmatha: 'मन्मथ', Durmukha: 'दुर्मुख' };
const wk = (i) => WK[L()][i];
const fd = (iso) => { const [y, m, d] = iso.split('-').map(Number); return L() === 'mr' ? `${n(d)} ${MON.mr[m - 1]} ${n(y)}` : `${d} ${MON.en[m - 1]} ${y}`; };
const tm = (s) => n(s);
const hrs = (x) => n(Math.abs(x).toFixed(1));
const tithiName = (r) => (L() === 'mr' ? r.tithi_mr : r.tithi_en);
const sv = (o, k) => (L() === 'mr' ? o[k + '_mr'] || SV_MR[o[k]] || o[k] : o[k]);

/** A day: weekday and date in its usual calendar, with the other calendar beside it. */
function dayText(r, { weekday = true, vara } = {}) {
  const w = weekday ? `${wk(vara ?? r.weekday)}, ` : '';
  if (r.usual === 'gregorian') return `${w}${fd(r.gregorian)}`;
  return `${w}${fd(r.julian)} (${t('sky.julian')}) = ${fd(r.gregorian)} (${t('sky.greg.back')})`;
}
const dayShort = (r) => (r.usual === 'gregorian' ? fd(r.gregorian) : `${fd(r.julian)} ${L() === 'mr' ? '(ज्यु.)' : '(Jul.)'}`);

// ---------------------------------------------------------------- evidence
const C = Object.fromEntries(SKY.claims.map((c) => [c.id, c]));
function claimEv(rows, extra = {}) {
  const cs = extra.cs || rows[0]?.claim_status;
  const src = [...new Set(rows.flatMap((r) => String(r.source_id || '').split(/;\s*/)).filter(Boolean))];
  return { cs, src, rows: [...rows.map((r) => r.date_claim_id), ...(extra.rows || [])], link: extra.link || 'life/dates',
    note: rows.map((r) => `${r.date_claim_id}: ${r.date_phrase}${r.note ? ' (' + r.note + ')' : ''}`) };
}
function calcEv(id, notes = []) {
  return { cs: 'reconstruction', rows: [`modules/sky/sky.js: ${id}`, 'tools/build_sky.py'], link: 'calendar/sky',
    note: [`Computed by ${SKY.generated_by} with ${SKY.library}.`, ...Object.entries(SKY.conventions).map(([k, v]) => `${k}: ${v}.`), SKY.accuracy.note, ...notes],
    srcObjs: [{ id: 'PyEphem', title: SKY.library }, { id: 'Meeus', title: 'J. Meeus, Astronomical Algorithms (2nd ed., 1998), ch. 49, used for the independent check of the Moon\'s phases' }] };
}

// ---------------------------------------------------------------- drawing
/** The lit part of the Moon for an elongation e (deg): waxing lit on the right, waning on the left. */
function moonDisk(cx, cy, r, e, cls = '') {
  const rad = (e * Math.PI) / 180, waxing = e < 180, cres = Math.cos(rad) > 0;
  const rx = Math.abs(Math.cos(rad)) * r;
  const d = `M${cx} ${cy - r}A${r} ${r} 0 0 ${waxing ? 1 : 0} ${cx} ${cy + r}A${rx.toFixed(2)} ${r} 0 0 ${waxing ? (cres ? 0 : 1) : (cres ? 1 : 0)} ${cx} ${cy - r}Z`;
  return `<g class="moon ${cls}"><circle class="dark" cx="${cx}" cy="${cy}" r="${r}"/><path class="lit" d="${d}"/><circle class="rim" cx="${cx}" cy="${cy}" r="${r}"/></g>`;
}
const STARS = [[18, 30], [44, 70], [70, 22], [96, 52], [128, 16], [152, 64], [176, 34], [204, 18], [222, 58], [250, 28], [276, 74], [298, 40], [114, 92], [236, 96], [30, 104], [306, 108]];
const azX = (az) => 10 + ((az - 30) / 300) * 300;
const altY = (alt) => 150 - alt * 1.45;
function dirKey(az) { const k = ['ne', 'e', 'se', 's', 'sw', 'w', 'nw']; const i = Math.round((az - 45) / 45); return k[Math.max(0, Math.min(k.length - 1, i))]; }
/** The night sky over Alandi with one or more Moons. moons: [{ sky, tag }]. */
function skySvg(moons, { label = '' } = {}) {
  const view = moons[0].sky.view, sunAlt = moons[0].sky.sun_alt;
  const starOp = sunAlt < -18 ? 0.9 : sunAlt < -12 ? 0.55 : 0.3;
  const glow = view === 'dawn' ? `<defs><radialGradient id="sky-glow" cx="${azX(112) / 320}" cy="1" r=".55"><stop offset="0" style="stop-color:var(--saffron);stop-opacity:.45"/>` +
    `<stop offset="1" style="stop-color:var(--saffron);stop-opacity:0"/></radialGradient></defs><rect x="0" y="0" width="320" height="150" fill="url(#sky-glow)"/>` : '';
  const ms = moons.map(({ sky, tag }) => {
    if (sky.moon_alt < 0) return `<g class="under">${moonDisk(azX(sky.moon_az), 166, 10, sky.elong, 'faint')}</g>`;
    const x = azX(sky.moon_az), y = altY(sky.moon_alt);
    return moonDisk(x, y, 12, sky.elong) + (tag ? `<text class="tag" x="${x + 17}" y="${y + 4}">${esc(n(tag))}</text>` : '');
  }).join('');
  return `<svg viewBox="0 0 320 190" role="img" aria-label="${esc(label)}"><rect class="skybg" x="0" y="0" width="320" height="190" rx="10"/>${glow}` +
    STARS.map(([x, y], k) => `<circle class="star" cx="${x}" cy="${y}" r="${k % 3 ? 0.9 : 1.3}" style="opacity:${starOp}"/>`).join('') +
    `<path class="ground" d="M0 150 C60 146 110 152 160 149 S260 147 320 150 V190 H0Z"/><path class="hz" d="M0 150 C60 146 110 152 160 149 S260 147 320 150"/>` +
    [['east', 90], ['south', 180], ['west', 270]].map(([k, az]) => `<text class="dir" x="${azX(az)}" y="172" text-anchor="middle">${esc(t('sky.' + k))}</text>`).join('') +
    ms + `</svg>`;
}
function skyCaption(sky) {
  const view = t('sky.v.' + sky.view), pct = n(Math.round(sky.illum * 100));
  if (sky.moon_alt < 0) return t('sky.sky.cap.below', { view, pct });
  return t('sky.sky.cap', { view, dir: t('sky.dir.' + dirKey(sky.moon_az)), alt: n(Math.round(sky.moon_alt)), pct });
}
/** Fifteen small Moons of the fortnight, the tithi's own marked. tnum 1..30. */
function fortnight(tnum) {
  const vadya = tnum > 15, k = vadya ? tnum - 16 : tnum - 1;
  const cells = Array.from({ length: 15 }, (_, i) => {
    const e = (vadya ? 180 : 0) + (i + 0.5) * 12, x = 11 + i * 21.2;
    return moonDisk(x, 14, 7, e, i === k ? 'on' : 'mini') + (i === k ? `<circle class="ring" cx="${x}" cy="14" r="10.5"/>` : '');
  }).join('');
  return `<figure class="fn"><svg viewBox="0 0 320 30" role="img" aria-label="${esc(t('sky.fn.label'))}">${cells}</svg>` +
    `<figcaption><span>${esc(t(vadya ? 'sky.fn.vadya' : 'sky.fn.shukla'))}</span></figcaption></figure>`;
}
/** The year as a ring of its lunar months. */
function yearRing(y) {
  const N = y.lunations.length, R = 62, cx = 160, cy = 100;
  const pts = y.lunations.map((l, i) => {
    const a = -Math.PI / 2 + (i / N) * 2 * Math.PI, x = cx + R * Math.cos(a), yy = cy + R * Math.sin(a);
    const lab = i === 0 || l.adhika ? `<text class="rlab" x="${cx + (R + 22) * Math.cos(a)}" y="${cy + (R + 22) * Math.sin(a) + 4}" text-anchor="middle">${esc((l.adhika ? (L() === 'mr' ? 'अधिक ' : 'adhika ') : '') + (L() === 'mr' ? l.mr : l.en))}</text>` : '';
    return moonDisk(x, yy, 8, 180, l.adhika ? 'on' : 'mini') + lab;
  }).join('');
  return `<svg viewBox="0 0 320 196" role="img" aria-label="${esc(t('sky.ring.label', { y: n(y.shaka) }))}"><circle class="orbit" cx="${cx}" cy="${cy}" r="${R}"/>${pts}` +
    `<text class="yr" x="${cx}" y="${cy + 2}" text-anchor="middle">${esc(L() === 'mr' ? 'शके ' + n(y.shaka) : 'Shaka ' + y.shaka)}</text></svg>`;
}

// ---------------------------------------------------------------- pieces of a screen
const kicker = (id) => `<p class="kick">${esc(t('sky.k.' + id))}</p>`;
const quote = (s, cls = '') => `<p class="q ${cls}" lang="mr">${esc(s)}</p>`;
const agree = (items) => `<div class="parts"><p class="ph">${esc(t('sky.parts'))}</p>` + items.map(([part, v, txt, partLang]) =>
  `<div class="pt"><p class="pp"><span${partLang ? ` lang="${partLang}"` : ''}>${esc(part)}</span> <b class="vd ${v}">${esc(t('sky.' + v))}</b></p><p class="px">${esc(txt)}</p></div>`).join('') + `</div>`;
const assumeBtn = (id) => `<button type="button" class="asb" data-assume="${esc(id)}">${esc(t('sky.assume'))}</button>`;
const calcHead = (id, notes) => `<p class="ch">${esc(t('sky.calc'))}${mark(calcEv(id, notes), { what: t('sky.calc.what') })}</p>`;
const night = (moons, sky, id, extra = '') => `<figure class="night">${skySvg(moons, { label: skyCaption(sky) })}` +
  `<figcaption>${esc(extra || skyCaption(sky))}${mark(calcEv(id + ' (sky)', [`Moon altitude ${sky.moon_alt} deg, azimuth ${sky.moon_az} deg, Sun altitude ${sky.sun_alt} deg, elongation ${sky.elong} deg at ${sky.time} local time. The drawing is schematic: directions along the horizon, height by altitude, the Moon's size exaggerated.`]), { what: t('sky.sky.what') })}</figcaption></figure>`;
const firstDay = (r) => r.days[0] || r.runs_on;

// ---------------------------------------------------------------- the screens
function sOpen() {
  const d = SKY.now.days[0];
  return `<div class="scr open">${night([{ sky: d.sky }], d.sky, 'now', t('sky.open.cap', { wd: wk(d.weekday), date: fd(d.gregorian), alt: n(Math.round(d.sky.moon_alt)) }))}
    <p class="lead">${esc(t('sky.open.1'))}</p><p class="lead2">${esc(t('sky.open.2'))}</p><p class="lead2">${esc(t('sky.open.3'))}</p>
    <p><button type="button" class="asb" data-method="1">${esc(t('sky.method'))}</button></p></div>`;
}

function sBirth() {
  const c = C.birth, r = c.computed.main, d = r.days[0];
  const dj = c.ce_check.readings.find((x) => x.read_as === 'julian');
  const ev = claimEv(c.claims, { rows: c.disputes });
  return `<div class="scr">${kicker('birth')}${quote(c.claims.find((x) => x.date_claim_id === 'DNYL-D004').date_phrase)}
    <p class="trad">${esc(t('sky.birth.trad'))}${mark(ev, { what: t('sky.trad.what') })}</p>
    ${night([{ sky: d.sky }], d.sky, 'birth')}${fortnight(23)}
    <div class="calc">${calcHead('birth')}
      <p class="cd">${esc(t('sky.birth.calc', { day: dayText(d, { vara: d.vara }), start: tm(r.tithi_start.time), end: tm(r.tithi_end.time) }))}</p>
      ${agree([
        [L() === 'mr' ? 'गुरुवार' : 'Thursday', d.vara === 4 ? 'ok' : 'no', t('sky.birth.p.wd', { wd: wk(d.vara) })],
        [L() === 'mr' ? '२२ ऑगस्ट १२७५' : '22 August 1275', d.gregorian === '1275-08-22' ? 'partly' : 'no', t('sky.birth.p.ce', { t: tithiName(dj) })],
        [L() === 'mr' ? 'युवा संवत्सर' : 'Yuva samvatsara', c.samvatsara_check.agrees_elapsed ? 'ok' : 'no', t('sky.birth.p.sv', { sv: sv(c.samvatsara_check, 'elapsed') })],
      ])}${assumeBtn('birth')}</div></div>`;
}

function sDny() {
  const c = C.dnyaneshwari, y = c.year;
  const ev = claimEv(c.claims.filter((x) => x.date_claim_id !== 'DNYL-D016'), { cs: 'disagreement', rows: ['DNYL-D016', ...c.disputes] });
  return `<div class="scr">${kicker('dnyaneshwari')}${quote(c.claims[0].date_phrase.replace(/\s*।\s*/, ' । ') + ' ॥', 'verse')}
    <p class="src xsmall">${esc(t('sky.dny.src'))} <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a> · <a href="#/read/18?seg=DNY18_1890">${esc(L() === 'mr' ? 'वाचनकक्षात' : 'in the reading room')}</a></p>
    <p class="trad">${esc(t('sky.dny.trad'))}${mark(ev, { what: t('sky.trad.what') })}</p>
    <figure class="ring">${yearRing(y)}</figure>
    <div class="calc">${calcHead('dnyaneshwari')}
      <p class="cd">${esc(t('sky.dny.calc', { first: dayText(y.first), last: dayText(y.last) }))}</p>
      ${agree([
        [L() === 'mr' ? 'इ.स. १२९०' : '1290 CE', 'ok', t('sky.dny.p.ce')],
        [L() === 'mr' ? 'संवत्सर' : 'Samvatsara', 'na', t('sky.dny.p.sv', { sv: L() === 'mr' ? y.samvatsara_mr : y.samvatsara })],
      ])}${assumeBtn('dnyaneshwari')}</div></div>`;
}

function samCard(r, which) {
  const d = firstDay(r);
  const body = r.kshaya
    ? t('sky.sam.kshaya', { m: n(Math.round((tmin(r.tithi_start.time) - tmin(d.sunrise)))), end: tm(r.tithi_end.time), wd: wk(d.weekday) })
    : t('sky.sam.normal', { start: tm(r.tithi_start.time) });
  return `<div class="card"><p class="cn"><b>${esc(n(which))}</b> ${esc(t(which === 1 ? 'sky.sam.a' : 'sky.sam.b'))}</p>` +
    `<svg viewBox="0 0 40 40" aria-hidden="true">${moonDisk(20, 20, 15, d.elong)}</svg>` +
    `<p class="cday">${esc(dayText(d))}</p><p class="cx">${esc(body)}</p></div>`;
}
const tmin = (s) => { const [h, m] = s.split(':').map(Number); return h * 60 + m; };

function sSamadhi() {
  const c = C.samadhi, a = c.computed.main, b = c.computed.surya_siddhanta, q = c.kartik_question;
  const ev = claimEv(c.claims.filter((x) => ['DNYL-D023', 'DNYL-D026', 'DNYL-D027', 'DNYL-D021', 'DNYL-D022'].includes(x.date_claim_id)), { rows: c.disputes });
  const da = firstDay(a), db = firstDay(b);
  return `<div class="scr">${kicker('samadhi')}${quote(L() === 'mr' ? 'कार्तिक वद्य त्रयोदशी, शके १२१८' : 'कार्तिक वद्य त्रयोदशी, शके १२१८')}
    <p class="trad">${esc(t('sky.sam.trad'))}${mark(ev, { what: t('sky.trad.what') })}</p>
    ${night([{ sky: da.sky, tag: 1 }, { sky: db.sky, tag: 2 }], da.sky, 'samadhi', t('sky.sam.pic'))}${fortnight(28)}
    <div class="calc">${calcHead('samadhi', [q.note, `Sun at the new moon of ${q.new_moon.julian} (Julian) ${q.new_moon.time} LMT: ${q.sun_lahiri} deg (Lahiri), ${q.sun_ss} deg (Surya Siddhanta).`])}
      <p class="cd">${esc(t('sky.sam.calc'))}</p>
      <div class="two">${samCard(a, 1)}${samCard(b, 2)}</div>
      <p class="hinge">${esc(t('sky.sam.hinge', { date: fd(q.new_moon.julian), a: n(q.short_by_lahiri_deg), h: n(Math.round(q.hours_of_sun)), b: n(q.past_by_ss_deg) }))}</p>
      ${agree([[L() === 'mr' ? 'शके १२१८, इ.स. १२९६' : 'Shaka 1218, 1296 CE', 'ok', t('sky.sam.p.ce')]])}${assumeBtn('samadhi')}</div></div>`;
}

function sSequence() {
  const c = C.samadhi;
  const ev = claimEv(c.claims.filter((x) => ['DNYL-D028', 'DNYL-D029'].includes(x.date_claim_id)), { link: 'connections/namdev' });
  const row = (list, which) => `<div class="seq"><p class="cn"><b>${esc(n(which))}</b> ${esc(t(which === 1 ? 'sky.sam.a' : 'sky.sam.b'))}</p><ol>` + list.map((x) => {
    const r = x.reading, d = firstDay(r), k = x.tithi - 16;
    const nm = L() === 'mr' ? ['दशमी', 'एकादशी', 'द्वादशी', 'त्रयोदशी'][k - 9] : ['Dashami', 'Ekadashi', 'Dvadashi', 'Trayodashi'][k - 9];
    return `<li><svg viewBox="0 0 30 30" aria-hidden="true">${moonDisk(15, 15, 11, d.elong)}</svg><b lang="${L()}">${esc(nm)}</b>` +
      `<span>${esc(wk(d.weekday))}</span><span>${esc(dayShort(d))}</span>${r.kshaya ? `<span class="ks">${esc(t('sky.seq.none'))}</span>` : ''}</li>`;
  }).join('') + `</ol></div>`;
  return `<div class="scr">${kicker('sequence')}${quote(c.claims.find((x) => x.date_claim_id === 'DNYL-D028').date_phrase)}
    <p class="trad">${esc(t('sky.seq.trad'))}${mark(ev, { what: t('sky.trad.what') })}</p>
    <div class="calc">${calcHead('sequence')}<p class="cd">${esc(t('sky.seq.calc'))}</p>${row(c.sequence.modern, 1)}${row(c.sequence.ss, 2)}${assumeBtn('samadhi')}</div></div>`;
}

function sWeekdays() {
  const c = C.weekdays, [va, vb] = c.voices;
  const ra = c.claims.find((x) => x.date_claim_id === 'DNYL-D025'), rb = c.claims.find((x) => x.date_claim_id === 'DNYL-D024');
  const a = va.computed.main, b = va.computed.surya_siddhanta;
  const r17 = vb.computed.main, d17 = firstDay(r17);
  const vx = voices([
    { who: t('sky.wk.a'), side: 'a', html: esc(ra.date_phrase), mark: mark(claimEv([ra], { rows: c.disputes }), { what: t('sky.wk.a') }) },
    { who: t('sky.wk.b'), side: 'b', html: esc(rb.date_phrase), mark: mark(claimEv([rb], { rows: c.disputes }), { what: t('sky.wk.b') }) },
  ], { label: t('sky.k.weekdays') });
  return `<div class="scr">${kicker('weekdays')}<p class="trad">${esc(t('sky.wk.trad'))}</p>${vx}
    <div class="calc">${calcHead('weekdays')}
      <p class="cd">${esc(t('sky.wk.calc.a'))}</p>
      ${agree([
        [L() === 'mr' ? 'दुर्मुख, शके १२१८' : 'Durmukha, Shaka 1218', va.samvatsara_check.agrees_elapsed ? 'ok' : 'no', t('sky.wk.a.sv')],
        [L() === 'mr' ? 'गुरुवार' : 'Thursday', [firstDay(a).weekday, firstDay(b).weekday].includes(4) ? 'ok' : 'no',
          t('sky.wk.a.wd', { w1: wk(firstDay(a).weekday), w2: wk(firstDay(b).weekday), wd: wk(b.tithi_start.vara), time: tm(b.tithi_start.time) })],
      ])}
      <p class="cd">${esc(t('sky.wk.calc.b'))}</p>
      ${agree([
        [L() === 'mr' ? 'रविवार, शके १२१७' : 'Sunday, Shaka 1217', d17.weekday === 0 ? 'ok' : 'no',
          t('sky.wk.b.shaka', { day: dayText(d17), m: n(Math.round(d17.margin_before_h * 60)) })],
        [L() === 'mr' ? 'दुर्मुख, शके १२१७' : 'Durmukha, Shaka 1217', vb.samvatsara_check.agrees_elapsed || vb.samvatsara_check.agrees_current ? 'ok' : 'no',
          t('sky.wk.b.sv', { sv: sv(vb.samvatsara_check, 'elapsed') })],
        [L() === 'mr' ? 'रविवार, २ डिसेंबर १२९६' : 'Sunday, 2 December 1296', 'partly', t('sky.wk.b.ce', { end: tm(a.tithi_end.time) })],
      ])}
      <p class="sum">${esc(t('sky.wk.sum'))}</p>${assumeBtn('weekdays')}</div></div>`;
}

function sEknath() {
  const c = C.eknath, y = c.year;
  const ev = claimEv(c.claims.filter((x) => x.date_claim_id !== 'DNYL-D020'), { rows: c.disputes });
  const k = c.claims.find((x) => x.date_claim_id === 'DNYL-D020');
  return `<div class="scr">${kicker('eknath')}${quote(c.claims[0].date_phrase + ' ॥', 'verse')}
    <p class="trad">${esc(t('sky.ek.trad'))}${mark(ev, { what: t('sky.trad.what') })}</p>
    <figure class="ring">${yearRing(y)}</figure>
    <div class="calc">${calcHead('eknath')}
      <p class="cd">${esc(t('sky.ek.calc', { first: dayText(y.first), last: dayText(y.last) }))}</p>
      ${agree([
        [L() === 'mr' ? 'तारण संवत्सर' : 'Tarana samvatsara', c.samvatsara_check.agrees_elapsed ? 'ok' : 'no', t('sky.ek.p.sv', { sv: sv(c.samvatsara_check, 'elapsed') })],
        [L() === 'mr' ? 'इ.स. १५८४' : '1584 CE', 'ok', t('sky.ek.p.ce')],
        [k.date_phrase.split('।')[0].trim(), 'na', t('sky.ek.p.kapila') , 'mr'],
      ])}${assumeBtn('eknath')}</div></div>`;
}

function sGatha() {
  const c = C.gatha1908, r = c.computed.main, d = r.days[0];
  return `<div class="scr">${kicker('gatha1908')}${quote(c.claims[0].date_phrase)}
    <p class="trad">${esc(t('sky.g.trad'))}${mark(claimEv(c.claims, { link: 'evidence/editions' }), { what: t('sky.trad.what') })}</p>
    ${night([{ sky: d.sky }], d.sky, 'gatha1908')}${fortnight(10)}
    <div class="calc">${calcHead('gatha1908')}
      <p class="cd">${esc(t('sky.g.calc', { day: dayText(d) }))}</p>
      ${agree([[L() === 'mr' ? 'शके १८३०' : 'Shaka 1830', 'ok', t('sky.g.p.ce')], [L() === 'mr' ? 'वार' : 'Weekday', 'na', t('sky.g.p.wd')]])}
      ${assumeBtn('gatha1908')}</div></div>`;
}

function sRest() {
  return `<div class="scr">${kicker('rest')}<p class="lead2">${esc(t('sky.rest.1'))}</p><p class="lead2">${esc(t('sky.rest.2'))}</p>
    <p><button type="button" class="asb" data-rest="1">${esc(t('sky.rest.list'))}</button></p>
    <div class="xdoors"><button type="button" class="xdoor" data-method="1"><span class="xd-t">${esc(t('sky.d.method'))}</span><span class="xd-l">${esc(t('sky.d.method.l'))}</span></button>
    ${door('#/samadhi', t('sky.d.sam'), t('sky.d.sam.l'))}${door('#/calendar/sky', t('sky.d.ws'), t('sky.d.ws.l'))}</div></div>`;
}

const SCREENS = [sOpen, sBirth, sDny, sSamadhi, sSequence, sWeekdays, sEknath, sGatha, sRest];

// ---------------------------------------------------------------- sheets
function readingRows(computed) {
  return `<table class="tb"><thead><tr><th>${esc(t('sky.as.col.r'))}</th><th>${esc(t('sky.as.col.d'))}</th><th>${esc(t('sky.as.col.m'))}</th></tr></thead><tbody>` +
    Object.entries(computed).map(([k, r]) => {
      const d = firstDay(r);
      const m = r.days[0] ? t('sky.hb', { b: hrs(r.days[0].margin_before_h), a: hrs(r.days[0].margin_after_h) }) : t('sky.kshaya.short');
      return `<tr><td>${esc(t('sky.r.' + k))}</td><td>${esc(wk(r.rule === 'midnight' ? d.vara ?? d.weekday : d.weekday))}, ${esc(dayShort(d))}</td>` +
        `<td>${esc(m)}<br><span class="xsmall">${esc(t('sky.mm', { d: n(r.month_margin_deg) }))}</span></td></tr>`;
    }).join('') + `</tbody></table>`;
}
function fixedAssumptions(rule) {
  return `<ul class="as">${['as.place', rule === 'midnight' ? 'as.tithi.midnight' : 'as.tithi.sunrise', 'as.month', 'as.ayan', 'as.year', 'as.cal']
    .map((k) => `<li>${esc(t('sky.' + k))}</li>`).join('')}<li>${esc(t('sky.as.eph', { dt: n(Math.round(SKY.accuracy.delta_t_1296_s)) }))}</li></ul>`;
}
function assumeSheet(id) {
  const c = C[id];
  let body = `<h3>${esc(t('sky.as.h'))}</h3>`;
  if (id === 'dnyaneshwari' || id === 'eknath') {
    const yc = id === 'dnyaneshwari' ? c.year_current : null;
    body += fixedAssumptions('sunrise') + `<h3>${esc(t('sky.as.alt'))}</h3><ul class="as">` +
      (yc ? `<li>${esc(t('sky.r.current_year'))}: ${esc(dayText(yc.first))} – ${esc(dayText(yc.last))}</li>` : '') +
      `<li>${esc(t('sky.r.current_year'))}: ${esc(L() === 'mr' ? 'संवत्सर' : 'samvatsara')} ${esc(sv(c.samvatsara_check || { elapsed: c.year.samvatsara, elapsed_mr: c.year.samvatsara_mr, current: yc?.samvatsara, current_mr: yc?.samvatsara_mr }, 'current'))}</li></ul>`;
  } else if (id === 'weekdays') {
    body += fixedAssumptions('sunrise') + `<h3>${esc(t('sky.as.alt'))}: ${esc(L() === 'mr' ? 'शके १२१७' : 'Shaka 1217')}</h3>${readingRows(c.voices[1].computed)}` +
      `<h3>${esc(t('sky.as.alt'))}: ${esc(L() === 'mr' ? 'शके १२१८' : 'Shaka 1218')}</h3>${readingRows(c.voices[0].computed)}`;
  } else {
    body += fixedAssumptions(c.rule) + `<h3>${esc(t('sky.as.alt'))}</h3>${readingRows(c.computed)}`;
    if (id === 'birth') body += `<p class="ev-d">${esc(t('sky.birth.year', { day: dayText(c.other_year.reading.days[0], { vara: c.other_year.reading.days[0].vara }) }))}</p>`;
  }
  body += `<p class="ev-d">${esc(t('sky.as.margin'))}</p><p class="ev-d">${esc(t('sky.as.mmargin'))}</p>` +
    `<p class="ev-d">${esc(t('sky.m.gen'))} ${mark(calcEv(id), { what: t('sky.calc.what') })}</p>`;
  openSheet({ title: t('sky.assume'), html: `<div class="x-sky-sheet">${body}</div>` });
}
const CASE_MR = {
  M1: 'आषाढी एकादशी २०२६', M2: 'आषाढी एकादशी २०२४', M3: 'कार्तिक वद्य एकादशी २०२६', M4: 'कार्तिक वद्य त्रयोदशी २०२६ (समाधी दिन)',
  M5: 'कार्तिक वद्य एकादशी २०२४', M6: 'ज्येष्ठ वद्य अष्टमी २०२४ (पालखी प्रस्थान)', M7: 'श्रावण वद्य अष्टमी २०२४ (जयंती)',
  H1: 'छत्रपती शिवाजी महाराजांचा जन्म: फाल्गुन वद्य तृतीया, शके १५५१', H2: 'राज्याभिषेक: ज्येष्ठ शुद्ध त्रयोदशी, शके १५९६',
  H3: 'शिवाजी महाराजांचे निधन: चैत्र पौर्णिमा, शके १६०२', H4: 'संभाजी महाराजांचे निधन: फाल्गुन अमावास्या, शके १६१०',
  H5: 'पानिपतचे तिसरे युद्ध: पौष शुद्ध अष्टमी, शके १६८२',
  E1: 'खग्रास सूर्यग्रहण, ३ जून १२३९ (ज्युलियन): अमावास्या', E2: 'सूर्यग्रहण, २ ऑगस्ट ११३३ (ज्युलियन): अमावास्या', E3: 'कोलंबसचे चंद्रग्रहण, २९ फेब्रुवारी १५०४ (ज्युलियन): पौर्णिमा',
};
function methodSheet() {
  const V = SKY.validation;
  const cal = (c) => (c === 'julian' ? (L() === 'mr' ? ' (ज्यु.)' : ' (Jul.)') : '');
  const caseRow = (c) => `<tr><td>${esc(L() === 'mr' ? CASE_MR[c.id] : c.label)}</td><td>${esc(fd(c.expect) + cal(c.calendar))}</td>` +
    `<td>${esc(c.computed.map((x) => fd(x) + cal(c.calendar)).join(', '))}<br><span class="xsmall">${esc((L() === 'mr' ? 'सूर्यसिद्धान्त: ' : 'Surya Siddhanta: ') + c.computed_ss.map(fd).join(', '))}</span></td>` +
    `<td class="${c.pass ? 'ok' : 'no'}">${esc(t(c.pass ? 'sky.pass' : 'sky.fail'))}</td></tr>`;
  const head = `<thead><tr><th>${esc(t('sky.m.t.case'))}</th><th>${esc(t('sky.m.t.exp'))}</th><th>${esc(t('sky.m.t.got'))}</th><th>${esc(t('sky.m.t.res'))}</th></tr></thead>`;
  const ss = V.surya_siddhanta_check;
  const at = (s) => { const [d, h] = s.split(' '); return `${fd(d)}, ${tm(h)}`; };
  const html = `<div class="x-sky-sheet"><p>${esc(t('sky.m.1'))}</p><p>${esc(t('sky.m.2'))}</p>
    <h3>${esc(t('sky.m.modern'))}</h3><table class="tb">${head}<tbody>${V.cases.filter((c) => c.kind === 'modern').map(caseRow).join('')}</tbody></table>
    <h3>${esc(t('sky.m.hist'))}</h3><table class="tb">${head}<tbody>${V.cases.filter((c) => c.kind === 'historical').map(caseRow).join('')}</tbody></table>
    <p class="ev-d">${esc(t('sky.m.os'))}</p>
    <h3>${esc(L() === 'mr' ? 'ग्रहणे' : 'Eclipses')}</h3><p>${esc(t('sky.m.ecl'))}</p><ul class="as">${V.eclipses.map((e) =>
      `<li>${esc(L() === 'mr' ? CASE_MR[e.id] : e.label)}: ${esc(at(e.pyephem_syzygy_ut))} UT; ${esc(t('sky.m.ecl.diff', { d: n(Math.abs(e.pyephem_minus_meeus_min)) }))}. <b>${esc(t(e.pass ? 'sky.pass' : 'sky.fail'))}</b></li>`).join('')}</ul>
    <p>${esc(t('sky.m.in'))}</p><p>${esc(t('sky.m.misc'))}</p>
    <p>${esc(t('sky.m.ss', { ss: at(ss.mesha_sankranti_2026_ss_ist), la: at(ss.mesha_sankranti_2026_lahiri_ist), d: n(ss.ss_minus_lahiri_sun_deg_1296) }))}</p>
    <p>${esc(t('sky.m.limits'))}</p><p class="ev-d">${esc(t('sky.m.gen'))} ${mark(calcEv('validation', ['Validation cases: ' + V.cases.map((c) => `${c.id} ${c.pass ? 'pass' : 'fail'}${c.history ? ' (' + c.history + ')' : ''}`).join('; ')]), { what: t('sky.calc.what') })}</p></div>`;
  openSheet({ title: t('sky.m.h'), html });
}
function restSheet() {
  const why = (c) => (c.era === 'Shaka' ? 'why.shaka' : /century|about/.test(c.era_year + c.date_phrase) ? 'why.period' : 'why.year');
  const html = `<div class="x-sky-sheet"><ul class="rest">${C.rest.claims.map((c) =>
    `<li><p${/[ऀ-ॿ]/.test(c.date_phrase) ? ' lang="mr"' : ' lang="en"'}>${esc(c.date_phrase)}</p><p class="xsmall">${esc(t('sky.' + why(c)))}${mark(claimEv([c]), { what: c.date_claim_id })}</p></li>`).join('')}</ul></div>`;
  openSheet({ title: t('sky.rest.list.h'), html });
}

// ---------------------------------------------------------------- page
export async function render(ctx) {
  const start = Math.max(0, Math.min(SCREENS.length - 1, (parseInt(ctx.query.get('p'), 10) || 1) - 1));
  ctx.el.innerHTML = `<div class="x-sky">${STYLE}<h1 tabindex="-1">${esc(t('x.sky'))}</h1><p class="sub">${esc(t('sky.sub'))}</p><div id="sky-pager"></div></div>`;
  ctx.el.addEventListener('click', (e) => {
    const a = e.target.closest('[data-assume]'); if (a) { assumeSheet(a.dataset.assume); return; }
    if (e.target.closest('[data-method]')) { methodSheet(); return; }
    if (e.target.closest('[data-rest]')) restSheet();
  });
  ctx.after = () => {
    pager(ctx.el.querySelector('#sky-pager'), {
      count: SCREENS.length, start, label: t('sky.pager'),
      render: (k) => SCREENS[k](),
      onChange: (k) => { const want = `#/sky${k ? `?p=${k + 1}` : ''}`; if (location.hash !== want) history.replaceState(null, '', want); },
    });
    if (ctx.query.get('p')) ctx.el.querySelector('#sky-pager').scrollIntoView({ block: 'start' });
  };
  ctx.manageScroll = !!ctx.query.get('p');
}

